  {tab==='home'&&user.role!=='admin'&&<div className="p-staff-overview"><div><span className="p-eyebrow">همراهی مؤثر، با پیگیری به‌موقع</span><h2>{user.role==='clinician'?'هر پرونده، فرصتی برای مراقبت بهتر':'از یک درخواست، تا یک هماهنگی روشن'}</h2><p>{user.role==='clinician'?'پرونده‌های تخصیص‌یافته را مرور کنید؛ نتیجهٔ بررسی شما مسیر پیگیری عضو را مشخص می‌کند.':'درخواست‌های اعضا را پیگیری کنید و پس از هماهنگی، مرکز، زمان و مرجع تأیید را ثبت کنید.'}</p></div><span className="p-staff-hero-icon"><Icon name={user.role==='clinician'?'doctor':'calendar'} size={46}/></span></div>}
  {tab==='home'&&user.role==='clinician'&&<div className="p-staff-stats">{[[queue?.members?.length||0,'پرونده تخصیص‌یافته','file'],[queue?.members?.filter((m:Obj)=>m.status==='submitted').length||0,'در انتظار بررسی','clock'],[queue?.members?.filter((m:Obj)=>m.urgent&&!m.urgent_resolved_at).length||0,'نیازمند پیگیری فوری','shield']].map(([n,l,i])=><div key={String(l)}><span><Icon name={String(i)}/></span><div><b>{fa(Number(n))}</b><small>{l}</small></div></div>)}</div>}
